components.customCSS:
i {
  color: #ff5577;
  font-size: 22px;
  filter: drop-shadow(0 0 6px rgba(255,85,119,0.6));
}

img {
  border-radius: 50%;
  box-shadow: 0 0 6px rgba(0, 200, 255, 0.5);
  border: 2px solid #00c8ff;
}

img {
  border-radius: 8px;
  object-fit: cover;
  transform: rotate(-2deg);
}

i {
  margin: 0 2px;
  font-size: 18px;
}
i.fa-heart { color: #ff5577; }
i.fa-heart-broken { color: rgba(255,255,255,0.35); }

progress {
  width: 240px;
  height: 14px;
  border-radius: 7px;
  overflow: hidden;
}
progress::-webkit-progress-bar {
  background: rgba(255,255,255,0.12);
  border-radius: 7px;
}
progress::-webkit-progress-value {
  background: linear-gradient(90deg, #f55, #ff5);
  border-radius: 7px;
}

streamOverlays.customCSS:
padding: 6px 10px;
border: 1px solid rgba(255, 255, 255, 0.4);
border-radius: 6px;
background-color: rgba(0, 0, 0, 0.35);
font-size: 18px;

components.customCSS:
padding: 4px 8px;
background: rgba(0, 0, 0, 0.35);
border-radius: 4px;
font-size: 20px;
color: #ffd470;
font-weight: 700;
letter-spacing: 0.5px;

i {
  color: #ff5577;
  font-size: 28px;
  filter: drop-shadow(0 0 6px rgba(255,85,119,0.6));
}

img {
  border-radius: 50%;
  box-shadow: 0 0 6px rgba(0, 200, 255, 0.5);
  border: 2px solid #00c8ff;
}

img {
  border-radius: 8px;
  object-fit: cover;
  transform: rotate(-2deg);
  width: 100%;
  height: 100%;
}

progress {
  width: 100%;
  height: 100%;
  border-radius: 7px;
  overflow: hidden;
}
progress::-webkit-progress-bar { background: rgba(255,255,255,0.12); }
progress::-webkit-progress-value { background: linear-gradient(90deg, #f55, #ff5); }
